def link(href,text):return f'<a href="{href}">{text}</a>'
def page(title,body,path='/',description='A briefing for LUNA holders on Philipp’s project funding, voting and retained authority, with dated source records.'):
    nav=''.join(f'<a href="{u}"'+(' aria-current="page"' if u==path else '')+f'>{t}</a>' for u,t in NAV)
    motion=motion_script() if 'data-motion-root' in body else ''
    out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · LUNA Holder Briefing</title><meta name="description" content="{e(description)}"><meta name="referrer" content="no-referrer"><meta name="robots" content="noindex,follow"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{SITE+path}"><meta name="theme-color" content="#203e35"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/site.css"><link rel="stylesheet" href="/visuals.css"><script defer src="/site.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap header-inner"><a class="brand" href="/">{MARK}<span>LUNA holder briefing<small>Philipp · public records</small></span></a><nav class="nav" aria-label="Main navigation">{nav}</nav></div></header><main id="main">{body}</main>{motion}<footer class="footer"><div class="wrap footer-inner"><div><p>Prepared for LUNA holders. Built from the public record.</p><p>Source material updated 25 October 2026. This is a dated snapshot, not a live feed.</p></div><nav aria-label="Footer"><a href="/sources/">Sources &amp; method</a><a href="/record/">Source record</a><a href="/privacy/">Privacy</a></nav></div></footer></body></html>'''
    file=DIST/('index.html' if path=='/' else path.strip('/')+'/index.html');file.parent.mkdir(parents=True,exist_ok=True);file.write_text(out)
def head(title,desc):return f'<div class="page-head"><div class="wrap"><p class="breadcrumb"><a href="/">Holder briefing</a></p><h1>{title}</h1><p>{desc}</p></div></div>'
def nextlinks(left,right):return f'<nav class="next-reading" aria-label="Continue reading">{link(*left)}{link(*right)}</nav>'
def evidence(id,title,body):return f'<details class="evidence-detail" id="{id}"><summary>{title}</summary><div>{body}</div></details>'

# Preserve every retrieved source byte before relocating the HTML presentation.
for p in (DIST/'record').rglob('*.html'):
    backup=ROOT/'source-records'/'original-pages'/p.relative_to(DIST/'record')
    if not backup.exists():backup.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,backup)
    s=backup.read_text()
    def relocate(m):
        attr,q,value=m.groups()
        if value.startswith('/') and not value.startswith('//'): value='/record'+value
        elif value.startswith(ORIGINAL): value='/record/'+value[len(ORIGINAL):]
        return attr+'='+q+value+q
    s=re.sub(r'(href|src|action)=([\'"])(.*?)\2',relocate,s)
    s=s.replace('<base href="/record/"/>','<base href="/record/"/>')
    banner='<div style="padding:12px 20px;background:#e9f1ed;color:#203e35;font:16px/1.4 sans-serif;text-align:center">Preserved source presentation · <a href="/" style="color:#203e35">Return to the holder briefing</a></div>'
    s=re.sub(r'(<body[^>]*>)',r'\1'+banner,s,count=1)
    p.write_text(s)

diagram='''<svg class="diagram-svg diagram-desktop" viewBox="0 0 480 464" role="img" aria-labelledby="estima-decision-title estima-decision-desc" xmlns="http://www.w3.org/2000/svg"><title id="estima-decision-title">Estima: from grant to payment</title><desc id="estima-decision-desc">The Estima grant was approved by the other three directors; Philipp voted for its kickoff release, and 45,000 USDC was paid to the project account.</desc><defs><marker id="estima-arrow" markerWidth="8" markerHeight="6" refX="7" refY="3" orient="auto"><path d="M0 0 8 3 0 6Z" fill="#526459"/></marker><marker id="estima-arrow-accent" markerWidth="8" markerHeight="6" refX="7" refY="3" orient="auto"><path d="M0 0 8 3 0 6Z" fill="#28654f"/></marker><marker id="estima-arrow-link" markerWidth="8" markerHeight="6" refX="7" refY="3" orient="auto"><path d="M0 0 8 3 0 6Z" fill="#28654f"/></marker></defs><g font-family="Source Sans 3, sans-serif"><text x="40" y="40" font-size="14" font-weight="600" fill="#203e35">Estima: from grant to payment</text><path d="M240 152V204" fill="none" stroke="#526459" stroke-width="1.5" marker-end="url(#estima-arrow)"/><path d="M240 288V340" fill="none" stroke="#28654f" stroke-width="1.5" marker-end="url(#estima-arrow-accent)"/><rect x="80" y="72" width="320" height="80" rx="6" fill="#ffffff" stroke="#8ba395"/><text x="104" y="100" font-size="12" font-weight="600" fill="#203e35">Grant approved · A266</text><text x="104" y="123" font-size="12" fill="#526459">125,000 USDC · other three directors</text><rect x="80" y="204" width="320" height="84" rx="6" fill="#e9f1ed" stroke="#28654f"/><text x="104" y="232" font-size="12" font-weight="600" fill="#203e35">Kickoff release · A271</text><text x="104" y="255" font-size="12" fill="#526459">Philipp voted YES as a beneficiary</text><rect x="80" y="340" width="320" height="64" rx="6" fill="#ffffff" stroke="#8ba395"/><text x="104" y="365" font-size="12" font-weight="600" fill="#203e35">Project account receives 45,000 USDC</text><text x="104" y="387" font-size="12" fill="#526459">Paid 3 October 2026</text><path d="M40 424H440" stroke="#cddbd3"/><text x="40" y="445" font-size="11" fill="#526459">80,000 USDC remained conditional and unpaid.</text></g></svg>'''
mobile_diagram=diagram.replace('diagram-svg diagram-desktop','diagram-svg diagram-mobile').replace('0 0 480 464','0 0 280 464').replace('estima-decision-title','estima-decision-mobile-title').replace('estima-decision-desc','estima-decision-mobile-desc').replace('estima-arrow','estima-mobile-arrow').replace('M240','M140').replace('x="80"','x="40"').replace('width="320"','width="200"').replace('x="104"','x="56"').replace('H440','H240').replace('Estima: from grant to payment</text>','Estima: grant to payment</text>').replace('125,000 USDC · other three directors</text>','125,000 USDC</text><text x="56" y="140" font-size="12" fill="#526459">Other three directors</text>').replace('Philipp voted YES as a beneficiary</text>','Philipp voted YES</text><text x="56" y="274" font-size="12" fill="#526459">Project beneficiary</text>').replace('Project account receives 45,000 USDC','45,000 USDC received').replace('Paid 3 October 2026','3 Oct 2026 · project account').replace('80,000 USDC remained conditional and unpaid.</text>','80,000 USDC remained</text><text x="40" y="460" font-size="11" fill="#526459">conditional and unpaid.</text>')
standalone=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Estima: from grant to payment</title><link href="https://fonts.googleapis.com/css2?family=Public+Sans:wght@400;600&amp;family=Source+Sans+3:wght@400;600&amp;display=swap" rel="stylesheet"><style>body{{margin:0;padding:24px;background:#fff;color:#203e35;font-family:'Source Sans 3',sans-serif}}main{{max-width:720px;margin:auto;min-width:0}}h1{{font-family:'Public Sans',sans-serif;font-size:28px;font-weight:600}}.diagram-scroll{{overflow-x:auto;width:100%}}svg{{display:block;width:100%;min-width:480px}}p{{font-size:16px;line-height:1.5}}a{{color:#28654f}}@media print{{.diagram-scroll{{overflow-x:visible}}svg{{min-width:0}}}}</style></head><body><main><h1>Estima: from grant to payment</h1><div class="diagram-scroll">{diagram}</div><p>A dated record of the grant, milestone release and payment. Source: Philipp Payments, supporting evidence, milestone records A266 and A271.</p></main></body></html>'''
